import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements Dijkstra's algorithm to find the shortest path in a weighted directed graph
    with non-negative weights. It uses a priority queue to efficiently retrieve the next node
    to process and updates distances accordingly.
    """
    heap = [(0, start)]  # Priority queue to hold (distance, node)
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    predecessors = {node: None for node in graph}

    while heap:
        current_distance, current_node = heapq.heappop(heap)

        # Early termination if we reach the end node
        if current_node == end:
            break

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                predecessors[neighbor] = current_node
                heapq.heappush(heap, (distance, neighbor))

    # Path reconstruction
    if distances[end] == float('inf'):
        return (float('inf'), [])

    path = []
    current = end
    while current is not None:
        path.append(current)
        current = predecessors[current]

    return (distances[end], path[::-1])
